<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useB1Store } from '../stores/b1'; import { dailyQuotaOptions, type DailyQuotaMinutes } from '../domain/b1'
const props = defineProps<{ section?: string }>(); const b1 = useB1Store(); const nickname = ref(''); const accent = ref<'US'|'UK'>('US'); const quota = ref<DailyQuotaMinutes>(15); const section = computed(() => props.section ?? 'profile')
onMounted(async () => { b1.restore(); await b1.loadAccountData(); nickname.value = b1.profile.nickname; accent.value = b1.profile.accentPref; quota.value = b1.profile.dailyQuotaMinutes })
async function save(): Promise<void> { await b1.saveProfile({ nickname: nickname.value.trim() || '学习者', accentPref: accent.value, dailyQuotaMinutes: quota.value }) }
async function exportData(): Promise<void> { const url = await b1.exportData(); if (url) window.open(url, '_blank') }
</script>
<template><section class="page-stack" aria-labelledby="settings-title"><div><p class="eyebrow">ACCOUNT & PRIVACY</p><h2 id="settings-title">设置</h2><p class="muted">你的目标、偏好和隐私选择都可以在这里调整。</p></div><nav class="settings-nav"><a :class="{active:section==='profile'}" href="/settings/profile">学习资料</a><a :class="{active:section==='privacy'}" href="/settings/privacy">隐私与数据</a><a :class="{active:section==='devices'}" href="/settings/devices">设备会话</a><a href="/platform">端与性能验收</a></nav><article v-if="section === 'profile'" class="form-card"><h3>学习资料</h3><label>昵称<input v-model="nickname" /></label><label>发音偏好<select v-model="accent"><option value="US">美式英语</option><option value="UK">英式英语</option></select></label><label>每日目标<select v-model="quota"><option v-for="item in dailyQuotaOptions" :key="item" :value="item">{{ item }} 分钟</option></select></label><button class="button button--primary" type="button" @click="save">保存修改</button></article><article v-else-if="section === 'privacy'" class="form-card"><h3>隐私与数据</h3><p class="muted">当前展示范围：{{ b1.privacy.leaderboardVisibility === 'NICKNAME' ? '昵称' : '匿名' }}；学习时长展示：{{ b1.privacy.showMinutes ? '开启' : '关闭' }}。</p><button class="button button--secondary" type="button" @click="exportData">申请导出我的数据</button></article><article v-else class="form-card"><h3>设备会话</h3><div v-for="device in b1.devices" :key="device.deviceId" class="device"><div><strong>{{ device.deviceName }}</strong><p>{{ device.region }} · {{ device.clientVersion }}</p></div><span>{{ device.current ? '当前设备' : device.status }}</span></div></article><p v-if="b1.lastError" class="error-text" role="alert">{{ b1.lastError }}</p></section></template>
<style scoped>.muted{color:var(--yx-color-text-secondary)}.settings-nav{display:flex;gap:8px;flex-wrap:wrap}.settings-nav a{padding:10px 14px;border-radius:10px;color:var(--yx-color-text-secondary)}.settings-nav a.active{color:var(--yx-color-brand-primary);background:var(--yx-color-brand-primary-soft)}.form-card{display:grid;gap:18px;padding:28px;border:1px solid var(--yx-color-border);border-radius:var(--yx-radius-card);background:#fff}.form-card h3{margin:0 0 6px;font-size:24px}.form-card label{display:grid;gap:8px;color:var(--yx-color-text-secondary);font-weight:600}.form-card input,.form-card select{padding:12px;border:1px solid var(--yx-color-border);border-radius:10px;background:#fff;color:inherit}.device{display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid var(--yx-color-border)}.device p{margin:6px 0 0;color:var(--yx-color-text-secondary);font-size:13px}.device>span{color:var(--yx-color-success);font-size:13px}.error-text{color:var(--yx-color-danger)}</style>
